package io.knowledgebrain.activity;
import java.time.*;import java.util.*;import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.integration.github.v1.GitHubCommitImportedV1;
final class GitHubActivity {
 static String path(UUID space,UUID repository,UUID commit){return "/api/spaces/"+space+"/github/repositories/"+repository+"/commits/"+commit;}
 static boolean target(ActivityEvent e){try{String[] p=e.targetPath().split("/",-1);return p.length==9&&p[1].equals("api")&&p[2].equals("spaces")&&ActivityEvent.id(p[3]).equals(e.spaceId())&&p[4].equals("github")&&p[5].equals("repositories")&&ActivityEvent.id(p[6])!=null&&p[7].equals("commits")&&ActivityEvent.id(p[8]).equals(e.aggregateId())&&e.roadmapId()==null&&e.nodeId()==null&&e.planning()==null&&e.content()==null&&e.note()==null&&e.noteConcepts()==null&&e.metadata()==null&&e.noteLinks()==null&&e.noteAttachments()==null&&e.claim()==null&&e.startedAt()==null&&e.endedAt()==null&&e.durationSeconds()==0&&e.sourceVersion()==1&&e.state().equals("IMPORTED")&&e.aggregateType().equals("GitHubCommit")&&e.eventType().equals("GitHubCommitImported");}catch(RuntimeException error){return false;}}
 static ActivityEvent decode(RoadmapEventEnvelopeV1 e)throws com.google.protobuf.InvalidProtocolBufferException{var p=GitHubCommitImportedV1.parseFrom(e.getPayload());UUID commit=ActivityEvent.id(p.getCommitId()),repo=ActivityEvent.id(p.getRepositoryId()),space=ActivityEvent.id(e.getSpaceId());if(!commit.equals(ActivityEvent.id(e.getAggregateId()))||!e.getAggregateType().equals("GitHubCommit")||!e.getEventType().equals("GitHubCommitImported")||p.getVersion()!=1||!p.getVisibility().equals("PRIVATE")||!p.getSourceVisibility().equals("PUBLIC")||!p.getRepositoryExternalId().matches("[1-9][0-9]{0,18}")||!p.getRepositoryFullName().matches("[A-Za-z0-9-]{1,39}/[A-Za-z0-9_.-]{1,100}")||!p.getSha().matches("(?:[0-9a-f]{40}|[0-9a-f]{64})")||!p.getUrl().equals("https://github.com/"+p.getRepositoryFullName()+"/commit/"+p.getSha())||p.getSubject().codePointCount(0,p.getSubject().length())>500||p.getSubject().codePoints().anyMatch(c->Character.isISOControl(c)||c>=0xd800&&c<=0xdfff)||!p.getAuthorLogin().isEmpty()&&!p.getAuthorLogin().matches("[A-Za-z0-9-]+(?:\\[bot\\])?")||Instant.parse(p.getImportedAt()).toEpochMilli()!=e.getOccurredAtEpochMillis())throw ActivityEvent.invalid();String at=Instant.parse(p.getCommittedAt()).toString();String detail="GitHub 커밋 시각: "+at+"\n"+p.getSubject()+(p.getAuthorLogin().isEmpty()?"":"\nGitHub 작성자: "+p.getAuthorLogin())+"\n개인 저장소 연결로 가져온 관측 기록이며 본인의 기여로 간주하지 않습니다.";return new ActivityEvent(commitEvent(e),space,ActivityEvent.id(e.getActorId()),e.getTraceId(),Instant.ofEpochMilli(e.getOccurredAtEpochMillis()).toString(),"GITHUB_COMMIT",e.getEventType(),"GitHubCommit",commit,1,null,null,p.getRepositoryFullName()+" · "+p.getSha().substring(0,12),"","IMPORTED",detail,null,null,0,path(space,repo,commit),null,null,null,null,null,null,null,null);}
 private static UUID commitEvent(RoadmapEventEnvelopeV1 e){return ActivityEvent.id(e.getEventId());}
}
